window.VIDEOS= {"welcome": {"title": "Overview", "chapters": [{"label": "Welcome", "start": 0.0}, {"label": "What it is", "start": 9.4}, {"label": "What's inside", "start": 20.03}, {"label": "Your role", "start": 32.04}], "transcript": ["Welcome to the US time tracking training. Every hour you work should show up on your paycheck, exactly as you worked it.", "Time tracking simply means recording the hours you work, every day. It is how Cisco processes payroll accurately, and stays in line with labor law.", "Here is what you will cover. Who tracks time, and where. Why it matters. The policy on timecards, breaks and overtime. The deadlines. And the alerts that keep you on track.", "You track your own time. This course takes about thirty minutes, and gives you everything you need to get it right."], "captions": [[1.45, 3.912, "Welcome to the US time tracking training."], [3.912, 8.597, "Every hour you work should show up on your paycheck, exactly as you worked it."], [9.947, 14.205, "Time tracking simply means recording the hours you work, every day."], [14.205, 19.227, "It is how Cisco processes payroll accurately, and stays in line with labor law."], [20.577, 22.365, "Here is what you will cover."], [22.365, 24.09, "Who tracks time, and where."], [24.09, 25.048, "Why it matters."], [25.048, 27.922, "The policy on timecards, breaks and overtime."], [27.922, 28.816, "The deadlines."], [28.816, 31.243, "And the alerts that keep you on track."], [32.593, 33.819, "You track your own time."], [33.819, 38.417, "This course takes about thirty minutes, and gives you everything you need to get it right."]]}, "who": {"title": "Who tracks time?", "chapters": [{"label": "Who tracks", "start": 0.0}, {"label": "Status can change", "start": 18.16}, {"label": "Check yours", "start": 29.18}, {"label": "Who it is for", "start": 48.77}], "transcript": ["The Fair Labor Standards Act, a federal wage and hour law, requires Cisco to track all hours worked for the US non-exempt employees, including interns and part-time employees. Tracking time ensures compliance, and accurate overtime pay.", "Your status can change during your time at Cisco, for example when your job role changes, or when you move to a state whose laws are stricter than federal law.", "To check your own status, look at your offer letter. Or open Workday, go to your profile, choose Job, and on the Position tab, read FLSA Exemption Status. No, eligible for overtime, means you are non-exempt. Yes, not eligible for overtime, means you are exempt.", "This course is for US non-exempt employees who track their time, and for the leaders who manage them."], "captions": [[1.45, 13.301, "The Fair Labor Standards Act, a federal wage and hour law, requires Cisco to track all hours worked for the US non-exempt employees, including interns and part-time employees."], [13.301, 17.365, "Tracking time ensures compliance, and accurate overtime pay."], [18.715, 28.379, "Your status can change during your time at Cisco, for example when your job role changes, or when you move to a state whose laws are stricter than federal law."], [29.729, 33.405, "To check your own status, look at your offer letter."], [33.405, 40.545, "Or open Workday, go to your profile, choose Job, and on the Position tab, read FLSA Exemption Status."], [40.545, 44.222, "No, eligible for overtime, means you are non-exempt."], [44.222, 47.969, "Yes, not eligible for overtime, means you are exempt."], [49.319, 55.271, "This course is for US non-exempt employees who track their time, and for the leaders who manage them."]]}, "workday": {"title": "One place: Workday", "chapters": [{"label": "One place", "start": 0.0}, {"label": "Only Workday", "start": 14.81}], "transcript": ["Workday is the official system for recording all hours worked, because it connects directly to Cisco's payroll. Accurate time in Workday means you are paid correctly, including overtime and on-call pay.", "No other tool is integrated with payroll. So hours recorded anywhere else never reach your paycheck."], "captions": [[1.45, 8.389, "Workday is the official system for recording all hours worked, because it connects directly to Cisco's payroll."], [8.389, 14.015, "Accurate time in Workday means you are paid correctly, including overtime and on-call pay."], [15.365, 17.919, "No other tool is integrated with payroll."], [17.919, 21.531, "So hours recorded anywhere else never reach your paycheck."]]}, "timecard": {"title": "Your timecard", "chapters": [{"label": "Auto-fill", "start": 0.0}, {"label": "Interns and part-time", "start": 14.26}, {"label": "Submit and edit", "start": 23.89}, {"label": "Time off", "start": 37.29}, {"label": "On-call", "start": 47.15}], "transcript": ["If you are a full-time employee, your timecard fills itself in every Monday morning, based on your standard schedule. If your hours differ, just edit the blocks that are wrong, or add extra hours.", "Interns and part-time employees are different. Their timecards start empty, so they create their own time blocks for each pay period.", "Submit as it is when your hours match. If you worked overtime or had a schedule change, edit before you submit. And if you need to fix something later, adjustments are allowed for up to ninety days.", "Record every absence in Workday too, such as Time2Give or jury duty. Time worked and time off both belong on your timecard.", "On-call time starts with your leader, who marks you as eligible in Workday. Once that is set, record your on-call hours in the on-call sections of your timecard. Not sure? Ask your leader."], "captions": [[1.45, 8.656, "If you are a full-time employee, your timecard fills itself in every Monday morning, based on your standard schedule."], [8.656, 13.461, "If your hours differ, just edit the blocks that are wrong, or add extra hours."], [14.811, 17.695, "Interns and part-time employees are different."], [17.695, 23.088, "Their timecards start empty, so they create their own time blocks for each pay period."], [24.438, 26.775, "Submit as it is when your hours match."], [26.775, 31.203, "If you worked overtime or had a schedule change, edit before you submit."], [31.203, 36.491, "And if you need to fix something later, adjustments are allowed for up to ninety days."], [37.841, 42.586, "Record every absence in Workday too, such as Time2Give or jury duty."], [42.586, 46.353, "Time worked and time off both belong on your timecard."], [47.703, 52.624, "On-call time starts with your leader, who marks you as eligible in Workday."], [52.624, 58.202, "Once that is set, record your on-call hours in the on-call sections of your timecard."], [58.202, 58.792, "Not sure?"], [58.792, 59.842, "Ask your leader."]]}, "rates": {"title": "8, 40 and beyond", "chapters": [{"label": "The standard", "start": 0.0}, {"label": "Overtime", "start": 7.67}, {"label": "1.5 times", "start": 17.83}, {"label": "Holidays", "start": 26.67}, {"label": "Double time", "start": 37.85}, {"label": "Approval", "start": 43.98}], "transcript": ["A standard full-time day in the US is 8 hours. A standard full-time week is 40.", "Anything you work above either of those thresholds, by day or by week, counts as overtime. Cisco applies this approach in every state.", "Overtime is paid at 1.5 times your regular rate, for every hour over 8 in a day, or over 40 in a week.", "Hours worked on a Cisco-observed US holiday also qualify as overtime. Workday recognizes holidays, so just enter your hours as usual.", "And once you go past 12 hours in a single day, the rate rises to double time.", "Always get your manager's approval before you work overtime, and record every hour in Workday, whether it was pre-approved or not."], "captions": [[1.45, 4.646, "A standard full-time day in the US is 8 hours."], [4.646, 6.869, "A standard full-time week is 40."], [8.219, 14.181, "Anything you work above either of those thresholds, by day or by week, counts as overtime."], [14.181, 17.029, "Cisco applies this approach in every state."], [18.379, 25.867, "Overtime is paid at 1.5 times your regular rate, for every hour over 8 in a day, or over 40 in a week."], [27.217, 32.358, "Hours worked on a Cisco-observed US holiday also qualify as overtime."], [32.358, 37.052, "Workday recognizes holidays, so just enter your hours as usual."], [38.402, 43.181, "And once you go past 12 hours in a single day, the rate rises to double time."], [44.531, 52.147, "Always get your manager's approval before you work overtime, and record every hour in Workday, whether it was pre-approved or not."]]}, "breaks": {"title": "Breaks that count", "chapters": [{"label": "Rest breaks", "start": 0.0}, {"label": "Meal breaks", "start": 11.09}, {"label": "Never", "start": 28.11}, {"label": "Missed meal", "start": 37.2}, {"label": "Missed rest", "start": 49.73}], "transcript": ["Rest breaks are 10 minutes, and they are paid. You get one in every 4 hours of work. They are already counted in your hours worked, so you never enter them on your timecard.", "Meal breaks are unpaid. Unpaid meal breaks are determined by the applicable work location state. Once you have worked 5 hours, you must be given 30 minutes or more, completely relieved of duty. After 10 hours, a second 30-minute meal break is due.", "Two things you cannot do. You cannot skip your meal break and stop working 30 minutes early, and you cannot bank break time to use later.", "If you were involuntarily prevented from taking a meal break, enter your hours as one continuous block, with no gap. Workday then generates the meal break payment in your next paycheck.", "For a missed rest break, follow the step-by-step instructions in the Help Zone article."], "captions": [[0.547, 3.17, "Rest breaks are 10 minutes, and they are paid."], [3.17, 5.279, "You get one in every 4 hours of work."], [5.279, 10.297, "They are already counted in your hours worked, so you never enter them on your timecard."], [11.647, 13.17, "Meal breaks are unpaid."], [13.17, 17.437, "Unpaid meal breaks are determined by the applicable work location state."], [17.437, 23.795, "Once you have worked 5 hours, you must be given 30 minutes or more, completely relieved of duty."], [23.795, 27.306, "After 10 hours, a second 30-minute meal break is due."], [28.656, 30.079, "Two things you cannot do."], [30.079, 36.4, "You cannot skip your meal break and stop working 30 minutes early, and you cannot bank break time to use later."], [37.75, 44.797, "If you were involuntarily prevented from taking a meal break, enter your hours as one continuous block, with no gap."], [44.797, 48.928, "Workday then generates the meal break payment in your next paycheck."], [50.278, 51.62, "For a missed rest break,"], [51.62, 55.05, "follow the step-by-step instructions in the Help Zone article."]]}, "payroll": {"title": "One payroll week", "chapters": [{"label": "The week", "start": 0.0}, {"label": "Thursday 8:00 PM Pacific", "start": 8.37}, {"label": "8 to 9 PM Pacific", "start": 19.17}, {"label": "Thursday 9:00 PM Pacific", "start": 25.94}, {"label": "Sunday 2:30 PM Pacific", "start": 33.97}, {"label": "Sunday 6:30 PM Pacific", "start": 45.03}], "transcript": ["Every pay period has one week that matters most: the week before payday. Here is how it unfolds.", "On Thursday at 8:00 PM Pacific, Workday automatically submits your timecard. Before then, enter your expected hours for Friday and the weekend.", "Avoid submitting manually between 8:00 and 9:00 PM Pacific, to prevent system conflicts.", "At 9:00 PM Pacific, timecards with overtime or on-call hours open for your leader to review.", "By Sunday at 2:30 PM Pacific, correct any Friday or weekend estimate that turned out wrong. Workday re-submits your timecard at that moment.", "Sunday at 6:30 PM Pacific is the final deadline for leaders. Anything not approved by then is automatically processed for payment."], "captions": [[1.45, 6.09, "Every pay period has one week that matters most: the week before payday."], [6.09, 7.573, "Here is how it unfolds."], [8.923, 13.981, "On Thursday at 8:00 PM Pacific, Workday automatically submits your timecard."], [13.981, 18.373, "Before then, enter your expected hours for Friday and the weekend."], [19.723, 25.142, "Avoid submitting manually between 8:00 and 9:00 PM Pacific, to prevent system conflicts."], [26.492, 33.169, "At 9:00 PM Pacific, timecards with overtime or on-call hours open for your leader to review."], [34.519, 40.874, "By Sunday at 2:30 PM Pacific, correct any Friday or weekend estimate that turned out wrong."], [40.874, 44.226, "Workday re-submits your timecard at that moment."], [45.576, 49.833, "Sunday at 6:30 PM Pacific is the final deadline for leaders."], [49.833, 54.728, "Anything not approved by then is automatically processed for payment."]]}, "alerts": {"title": "Fix it before payday", "chapters": [{"label": "Alerts", "start": 0.0}, {"label": "Overlap", "start": 9.46}, {"label": "Daily total", "start": 25.49}, {"label": "On-call", "start": 38.34}, {"label": "Missing time", "start": 47.67}], "transcript": ["Workday watches your timecard for mistakes, and sends an alert when something looks off. When it does, act on it right away.", "First, overlap. You booked time off after your timecard filled in, so the same day now holds both hours worked and time off. Policy does not allow overlapping records, so reconcile them. Better still, book time off in advance.", "Second, daily total. Say you logged 4 hours of time off and 6 hours of work. That is 10, over your 8-hour day. Your worked hours are a fact, so reduce the time off to 2.", "Third, on-call. If you are on-call eligible, do not record both on-call hours worked and on-call standby for the same week.", "Last, missing time. Part-time employees and interns create their own entries. If you get a missing time reminder, log in and submit your hours right away."], "captions": [[1.45, 6.609, "Workday watches your timecard for mistakes, and sends an alert when something looks off."], [6.609, 8.661, "When it does, act on it right away."], [10.011, 10.998, "First, overlap."], [10.998, 18.106, "You booked time off after your timecard filled in, so the same day now holds both hours worked and time off."], [18.106, 22.121, "Policy does not allow overlapping records, so reconcile them."], [22.121, 24.688, "Better still, book time off in advance."], [26.038, 27.423, "Second, daily total."], [27.423, 31.233, "Say you logged 4 hours of time off and 6 hours of work."], [31.233, 33.519, "That is 10, over your 8-hour day."], [33.519, 37.537, "Your worked hours are a fact, so reduce the time off to 2."], [38.887, 39.868, "Third, on-call."], [39.868, 46.865, "If you are on-call eligible, do not record both on-call hours worked and on-call standby for the same week."], [48.215, 49.469, "Last, missing time."], [49.469, 53.229, "Part-time employees and interns create their own entries."], [53.229, 58.242, "If you get a missing time reminder, log in and submit your hours right away."]]}, "leader": {"title": "The leader playbook", "chapters": [{"label": "Your role", "start": 0.0}, {"label": "Your team", "start": 7.26}, {"label": "What reaches you", "start": 14.01}, {"label": "Review", "start": 28.78}, {"label": "Talk first", "start": 36.83}, {"label": "Alerts for you", "start": 47.73}, {"label": "Your people", "start": 57.21}, {"label": "Delegate", "start": 64.43}, {"label": "Sunday 6:30 PM Pacific", "start": 73.65}], "transcript": ["As a leader of non-exempt employees, your review is what keeps timecards accurate.", "Make sure your team completes this training, and knows the program, the resources, and the process.", "Timecards with overtime or on-call hours reach you on Thursday at 9:00 PM Pacific, with a notification in Workday and by email. Timecards with only regular hours are approved automatically.", "Even so, review regularly. Make it a ritual, and validate that your team's reported hours are accurate.", "If something is wrong, do not use Send Back in Workday. Talk with your team member directly. A conversation makes the correction clear, and builds better habits.", "Workday also alerts you when a part-time employee or intern has not entered time, or when records overlap. Follow up promptly.", "Encourage your team to take their required rest and meal breaks, and talk about schedules in your one-to-ones.", "Make sure a delegate is always assigned to approve on your behalf, especially during time off, unscheduled absences, or leave.", "Your final deadline is Sunday at 6:30 PM Pacific. After that, anything unapproved is processed for payment as it stands."], "captions": [[1.45, 6.463, "As a leader of non-exempt employees, your review is what keeps timecards accurate."], [7.813, 13.211, "Make sure your team completes this training, and knows the program, the resources, and the process."], [14.561, 23.625, "Timecards with overtime or on-call hours reach you on Thursday at 9:00 PM Pacific, with a notification in Workday and by email."], [23.625, 27.979, "Timecards with only regular hours are approved automatically."], [29.329, 31.037, "Even so, review regularly."], [31.037, 36.028, "Make it a ritual, and validate that your team's reported hours are accurate."], [37.378, 40.684, "If something is wrong, do not use Send Back in Workday."], [40.684, 42.848, "Talk with your team member directly."], [42.848, 46.935, "A conversation makes the correction clear, and builds better habits."], [48.285, 55.178, "Workday also alerts you when a part-time employee or intern has not entered time, or when records overlap."], [55.178, 56.413, "Follow up promptly."], [57.763, 63.63, "Encourage your team to take their required rest and meal breaks, and talk about schedules in your one-to-ones."], [64.98, 72.852, "Make sure a delegate is always assigned to approve on your behalf, especially during time off, unscheduled absences, or leave."], [74.202, 77.707, "Your final deadline is Sunday at 6:30 PM Pacific."], [77.707, 82.714, "After that, anything unapproved is processed for payment as it stands."]]}, "lead-welcome": {"title": "Overview", "chapters": [{"label": "Welcome", "start": 0.0}, {"label": "Why it matters", "start": 9.87}, {"label": "What employees do", "start": 22.82}, {"label": "What you do", "start": 33.45}, {"label": "This path", "start": 42.74}], "transcript": ["This path is for people leaders of US non-exempt employees. Your review and approval keep every hour on the right paycheck.", "The Fair Labor Standards Act requires Cisco to track hours worked for non-exempt employees. Accurate timecards support compliance, operational efficiency, and employee well-being.", "Employees record the hours they work in Workday, every day. That record is how payroll pays regular time, overtime, and on-call correctly.", "You review, validate, and approve those timecards. You also make sure your team knows the program, the deadlines, and where to get help.", "This path has three lessons and takes about 12 minutes to complete. You will cover the Introduction and Purpose, Time Tracking Essentials, and Actions and Deadlines for People Leaders. Resources and an acknowledgement follow."], "captions": [[1.45, 5.133, "This path is for people leaders of US non-exempt employees."], [5.133, 9.066, "Your review and approval keep every hour on the right paycheck."], [10.416, 16.349, "The Fair Labor Standards Act requires Cisco to track hours worked for non-exempt employees."], [16.349, 22.021, "Accurate timecards support compliance, operational efficiency, and employee well-being."], [23.371, 27.368, "Employees record the hours they work in Workday, every day."], [27.368, 32.651, "That record is how payroll pays regular time, overtime, and on-call correctly."], [34.001, 36.941, "You review, validate, and approve those timecards."], [36.941, 41.937, "You also make sure your team knows the program, the deadlines, and where to get help."], [43.3, 47.135, "This path has three lessons and takes about 12 minutes to complete."], [47.315, 54.058, "You will cover the Introduction and Purpose, Time Tracking Essentials, and Actions and Deadlines for People Leaders."]]}, "lead-timecard": {"title": "The employee timecard", "chapters": [{"label": "Auto-fill", "start": 0.0}, {"label": "Interns and part-time", "start": 12.92}, {"label": "Submit and edit", "start": 21.63}, {"label": "Time off", "start": 33.69}, {"label": "On-call", "start": 48.43}], "transcript": ["Full-time employees see a timecard that fills itself every Monday from their standard schedule. If the hours differ, they edit the blocks that are wrong, or add extra hours.", "Interns and part-time employees start with an empty timecard. They create their own time blocks for each pay period.", "Employees submit when the hours match. If they worked overtime or the schedule changed, they edit before they submit. Later adjustments are allowed for up to ninety days.", "If an employee books time off after the week was auto-populated, they delete the conflicting Hours Worked entries. Combined daily recorded time cannot exceed the scheduled day. The standard is 8 hours.", "You manage on-call eligibility in Workday. Once an employee is eligible, they record on-call time in the on-call sections of the timecard."], "captions": [[1.45, 7.341, "Full-time employees see a timecard that fills itself every Monday from their standard schedule."], [7.341, 12.117, "If the hours differ, they edit the blocks that are wrong, or add extra hours."], [13.467, 17.371, "Interns and part-time employees start with an empty timecard."], [17.371, 20.827, "They create their own time blocks for each pay period."], [22.177, 24.599, "Employees submit when the hours match."], [24.599, 29.571, "If they worked overtime or the schedule changed, they edit before they submit."], [29.571, 32.886, "Later adjustments are allowed for up to ninety days."], [34.236, 41.911, "If an employee books time off after the week was auto-populated, they delete the conflicting Hours Worked entries."], [41.911, 46.018, "Combined daily recorded time cannot exceed the scheduled day."], [46.018, 47.633, "The standard is 8 hours."], [48.983, 51.822, "You manage on-call eligibility in Workday."], [51.822, 58.242, "Once an employee is eligible, they record on-call time in the on-call sections of the timecard."]]}, "lead-breaks": {"title": "Meal and rest breaks", "chapters": [{"label": "Rest breaks", "start": 0.0}, {"label": "Meal breaks", "start": 13.03}, {"label": "Missed meal", "start": 35.96}, {"label": "Missed rest", "start": 49.47}], "transcript": ["A rest break is 10 minutes, paid, in every 4 hours of work. It is already inside hours worked, so employees do not enter it on the timecard. A rest break cannot be skipped or banked.", "Unpaid meal breaks follow the work-location state. At this time, employees must receive 30 minutes or more once they have worked 5 hours, and a second meal break after more than 10 hours. During a meal they must be completely relieved of duty and allowed to leave the premises, or that time is hours worked. A meal break cannot be skipped or banked.", "If an employee is involuntarily prevented from taking a meal break, they enter the hours as one continuous block, with no gap. Workday then generates the meal-break payment on the next paycheck.", "For a missed rest break, the employee gives you the Notice of Involuntarily Missed Rest Break form for review, approval, and signature."], "captions": [[0.007, 3.832, "A rest break is 10 minutes, paid, in every 4 hours of work."], [3.832, 9.018, "It is already inside hours worked, so employees do not enter it on the timecard."], [9.018, 11.676, "A rest break cannot be skipped or banked."], [13.026, 16.146, "Unpaid meal breaks follow the work-location state."], [16.146, 24.632, "At this time, employees must receive 30 minutes or more once they have worked 5 hours, and a second meal break after more than 10 hours."], [24.632, 32.057, "During a meal they must be completely relieved of duty and allowed to leave the premises, or that time is hours worked."], [32.057, 34.615, "A meal break cannot be skipped or banked."], [35.965, 43.904, "If an employee is involuntarily prevented from taking a meal break, they enter the hours as one continuous block, with no gap."], [43.904, 48.125, "Workday then generates the meal-break payment on the next paycheck."], [49.475, 57.475, "For a missed rest break, the employee gives you the Notice of Involuntarily Missed Rest Break form for review, approval, and signature."]]}, "lead-rates": {"title": "8, 40, and your approval", "chapters": [{"label": "The standard", "start": 0.0}, {"label": "Overtime", "start": 6.86}, {"label": "1.5 times", "start": 16.57}, {"label": "Holidays", "start": 25.43}, {"label": "Double time", "start": 37.62}, {"label": "Your approval", "start": 42.12}], "transcript": ["A standard full-time day is 8 hours. A standard full-time week is 40.", "Hours an employee works above either threshold, by day or by week, count as overtime. Cisco applies this in every state.", "Overtime is paid at 1.5 times the regular rate for every hour over 8 in a day, or over 40 in a week.", "Hours worked on a Cisco-observed US holiday also qualify as overtime. Employees enter those hours as hours worked, and Workday treats them as overtime.", "Hours past 12 in a single day are paid at double time.", "Employees need your approval before they start overtime. If something unforeseen stops them asking first, they report the hours in Workday immediately and email you as soon as they can. Every overtime hour is recorded, whether you approved it in advance or not."], "captions": [[1.45, 3.89, "A standard full-time day is 8 hours."], [3.89, 6.058, "A standard full-time week is 40."], [7.408, 13.381, "Hours an employee works above either threshold, by day or by week, count as overtime."], [13.381, 15.771, "Cisco applies this in every state."], [17.121, 24.63, "Overtime is paid at 1.5 times the regular rate for every hour over 8 in a day, or over 40 in a week."], [25.98, 30.965, "Hours worked on a Cisco-observed US holiday also qualify as overtime."], [30.965, 36.817, "Employees enter those hours as hours worked, and Workday treats them as overtime."], [38.167, 41.325, "Hours past 12 in a single day are paid at double time."], [42.675, 46.291, "Employees need your approval before they start overtime."], [46.291, 54.557, "If something unforeseen stops them asking first, they report the hours in Workday immediately and email you as soon as they can."], [54.557, 59.4, "Every overtime hour is recorded, whether you approved it in advance or not."]]}, "lead-payroll": {"title": "One payroll week", "chapters": [{"label": "The week", "start": 0.0}, {"label": "Thursday 8:00 PM Pacific", "start": 9.25}, {"label": "8 to 9 PM Pacific", "start": 21.37}, {"label": "Thursday 9:00 PM Pacific", "start": 31.51}, {"label": "Friday reminder", "start": 43.16}, {"label": "Sunday 2:30 PM Pacific", "start": 51.6}, {"label": "Sunday 6:30 PM Pacific", "start": 62.14}], "transcript": ["Every pay period has one week that matters most: the week before payday. Here is what your team does, and what you do.", "On Thursday at 8:00 PM Pacific, Workday automatically submits employee timecards. Before then, employees enter their expected hours for Friday and the weekend.", "Employees should not submit manually between 8:00 and 9:00 PM Pacific. A manual submit in that window can cause system conflicts.", "At 9:00 PM Pacific, timecards with overtime or on-call open for your review. Workday and email notify you when a timecard is over the standard week.", "On Friday of that week, you receive a reminder to approve your team's timecards before automatic processing on Sunday.", "Sunday at 2:30 PM Pacific is the last moment employees can correct Friday or weekend hours. Workday re-submits at that moment.", "Sunday at 6:30 PM Pacific is your final deadline to review and approve. Anything still unapproved is processed for payment as it stands."], "captions": [[1.45, 5.756, "Every pay period has one week that matters most: the week before payday."], [5.756, 8.447, "Here is what your team does, and what you do."], [9.797, 15.32, "On Thursday at 8:00 PM Pacific, Workday automatically submits employee timecards."], [15.32, 20.571, "Before then, employees enter their expected hours for Friday and the weekend."], [21.921, 26.727, "Employees should not submit manually between 8:00 and 9:00 PM Pacific."], [26.727, 30.71, "A manual submit in that window can cause system conflicts."], [32.06, 37.387, "At 9:00 PM Pacific, timecards with overtime or on-call open for your review."], [37.387, 42.364, "Workday and email notify you when a timecard is over the standard week."], [43.714, 50.797, "On Friday of that week, you receive a reminder to approve your team's timecards before automatic processing on Sunday."], [52.147, 58.84, "Sunday at 2:30 PM Pacific is the last moment employees can correct Friday or weekend hours."], [58.84, 61.341, "Workday re-submits at that moment."], [62.691, 67.662, "Sunday at 6:30 PM Pacific is your final deadline to review and approve."], [67.662, 72.142, "Anything still unapproved is processed for payment as it stands."]]}, "lead-playbook": {"title": "The leader playbook", "chapters": [{"label": "Your role", "start": 0.0}, {"label": "Confirm status", "start": 10.83}, {"label": "On-call eligibility", "start": 23.93}, {"label": "Your team", "start": 32.21}, {"label": "Review ritual", "start": 38.96}, {"label": "Talk first", "start": 50.42}, {"label": "Alerts for you", "start": 59.92}, {"label": "Breaks and one-to-ones", "start": 75.67}, {"label": "Delegate", "start": 83.98}, {"label": "Sunday 6:30 PM Pacific", "start": 93.75}], "transcript": ["If you were asked to take this training, you lead at least one US non-exempt employee. Your review is what keeps their timecards accurate.", "To confirm, open the team member's profile in Workday, select the Position tab, and read FLSA Exemption Status. No, eligible for overtime, means non-exempt.", "You also manage on call eligibility in Workday. Use the manager section of the global on-call article for guidance.", "Make sure your team completes this training, and knows the program, the resources, and the process.", "Timecards with only regular hours are approved automatically at submission. Review anyway. Make it a ritual, and check that the reported hours are accurate.", "If something is wrong, do not use Send Back. Talk with the employee. A conversation makes the correction clear, and builds better habits.", "Follow up immediately when Workday alerts you that a part-time employee or intern has not entered time. Also resolve overlap alerts: hours worked against time off, and on-call standby against on-call hours worked.", "Encourage the team to take required rest and meal breaks, and use one-to-ones to talk through schedules and discrepancies.", "Always assign a delegate to approve on your behalf, including for an unscheduled absence, extended time off, or a leave of absence.", "Your hard stop is Sunday at 6:30 PM Pacific. Review the Explore the Week video below for every deadline in between."], "captions": [[1.45, 6.833, "If you were asked to take this training, you lead at least one US non-exempt employee."], [6.833, 10.026, "Your review is what keeps their timecards accurate."], [11.376, 19.794, "To confirm, open the team member's profile in Workday, select the Position tab, and read FLSA Exemption Status."], [19.794, 23.131, "No, eligible for overtime, means non-exempt."], [24.48, 27.447, "You also manage on call eligibility in Workday."], [27.567, 31.746, "Use the manager section of the global on-call article for guidance."], [32.764, 38.161, "Make sure your team completes this training, and knows the program, the resources, and the process."], [39.511, 44.436, "Timecards with only regular hours are approved automatically at submission."], [44.436, 45.355, "Review anyway."], [45.355, 49.623, "Make it a ritual, and check that the reported hours are accurate."], [50.973, 53.629, "If something is wrong, do not use Send Back."], [53.629, 55.018, "Talk with the employee."], [55.018, 59.123, "A conversation makes the correction clear, and builds better habits."], [60.473, 67.469, "Follow up immediately when Workday alerts you that a part-time employee or intern has not entered time."], [67.469, 74.873, "Also resolve overlap alerts: hours worked against time off, and on-call standby against on-call hours worked."], [76.223, 83.177, "Encourage the team to take required rest and meal breaks, and use one-to-ones to talk through schedules and discrepancies."], [84.527, 92.954, "Always assign a delegate to approve on your behalf, including for an unscheduled absence, extended time off, or a leave of absence."], [94.304, 97.385, "Your hard stop is Sunday at 6:30 PM Pacific."], [98.58, 102.454, "Review the Explore the Week video below for every deadline in between."]]}, "how-view-timecard": {"title": "How do I view my timecard?", "transcript": ["Want to know how to view your timecard in Workday? From the Workday welcome page, click Personal in the menu on the left, then select Time.", "You have three choices. This Week for your current period, Last Week for the previous one. Or Select Week to access any specific time frame you need. For now, let's click This Week to see your timecard for the current period."], "captions": [[0.44, 3.04, "Want to know how to view your timecard in Workday?"], [4.68, 9.88, "From the Workday welcome page, click Personal in the menu on the left, then select Time."], [14.599, 19.76, "You have three choices. This Week for your current period, Last Week for the previous one."], [20.12, 23.399, "Or Select Week to access any specific time frame you need."], [23.879, 27.799, "For now, let's click This Week to see your timecard for the current period."]]}, "how-update-timecard": {"title": "How do I update my timecard?", "transcript": ["Welcome to this video on updating your timecards in Workday. First, let's explore how to update an existing time block to reflect your actual hours. If you worked longer or less than planned, click the time block you wish to adjust. Here, I am changing an end time from 5:00 PM to 9:00 PM. Once you update the time and press OK, the system recalculates your totals. You will see the daily total update to 12 hours in the bottom right corner, and the summary on the right will now accurately display your 4 hours of overtime.", "Next, let's see how to add a new time block to your card. To add time, click on the specific day. Select a time type. Hours Worked is selected by default, but you can choose a different type if needed, such as on-call standby or on-call hours worked. Enter your start and end times. In this case, 8:00 AM to 12:00 PM. And press OK. The new block will appear on your card, successfully recording your time for that day.", "Now, let's learn how to save time by bulk adding entries. For entries on multiple days, go to the Actions menu in the top right and select Quick Add. Select the appropriate week and click Next. Choose your time type, click Next, and enter your start and end times, such as 8:00 AM to 12:00 PM. Select the specific days, Thursday and Friday in this example, and before pressing OK, you can click Add to include another block of time over several days. Once you press OK, all your time blocks are added to your card simultaneously, effectively streamlining your entry process.", "Finally, let's look at how to remove incorrect entries by deleting a time block. If you have recorded hours on a day you didn't work, like a holiday, you can easily remove them. Simply click on the existing time block, select the Delete option, and confirm. Repeat this process for any additional blocks you need to clear. Your timecard will update immediately to reflect the removal."], "captions": [[1.3, 4.419, "Welcome to this video on updating your timecards in Workday."], [5.26, 10.14, "First, let's explore how to update an existing time block to reflect your actual hours."], [10.62, 14.899, "If you worked longer or less than planned, click the time block you wish to adjust."], [15.34, 18.18, "Here, I am changing an end time from 5:00 PM"], [18.379, 21.06, "to 9:00 PM. Once you update the time and press"], [21.26, 23.939, "OK, the system recalculates your totals."], [24.26, 28.349, "You will see the daily total update to 12 hours in the bottom right corner,"], [28.349, 32.819, "and the summary on the right will now accurately display your 4 hours of overtime."], [34.819, 37.94, "Next, let's see how to add a new time block to your card."], [38.28, 40.239, "To add time, click on the specific day."], [40.88, 44.084, "Select a time type. Hours Worked is selected by default,"], [44.084, 49.52, "but you can choose a different type if needed, such as on-call standby or on-call hours worked."], [51.64, 53.2, "Enter your start and end times."], [53.67, 55.79, "In this case, 8:00 AM to 12:00 PM."], [56.27, 57.531, "And press OK."], [57.531, 65.87, "The new block will appear on your card, successfully recording your time for that day."], [66.79, 69.789, "Now, let's learn how to save time by bulk adding entries."], [70.32, 75.24, "For entries on multiple days, go to the Actions menu in the top right and select Quick Add."], [80.24, 82.16, "Select the appropriate week and click Next."], [83.919, 89.08, "Choose your time type, click Next, and enter your start and end times, such as 8:00 AM"], [89.28, 90.042, "to 12:00 PM."], [90.042, 93.977, "Select the specific days, Thursday and Friday in this example,"], [93.977, 99.879, "and before pressing OK, you can click Add to include another block of time over several days."], [100.999, 108.28, "Once you press OK, all your time blocks are added to your card simultaneously, effectively streamlining your entry process."], [110.09, 114.61, "Finally, let's look at how to remove incorrect entries by deleting a time block."], [114.97, 120.21, "If you have recorded hours on a day you didn't work, like a holiday, you can easily remove them."], [121.01, 125.53, "Simply click on the existing time block, select the Delete option, and confirm."], [126.28, 128.84, "Repeat this process for any additional blocks you need to clear."], [129.279, 132.32, "Your timecard will update immediately to reflect the removal."]]}, "how-missed-meal": {"title": "How do I report an involuntarily missed meal break?", "transcript": ["How do I report an involuntarily missed meal break? Employees are required to take an unpaid 30-minute meal break after working 5 hours or more. If you are involuntarily prevented from taking your break, you must report it on your timecard by entering your total hours worked consecutively, without a gap.", "In this example, we are entering hours from 8:00 AM to 2:00 PM, amounting to six consecutive hours. After pressing OK, you will immediately see the meal break penalty appear on your timecard.", "After submission, this will require your manager's approval. Workday will then automatically process the appropriate compensation in your next paycheck."], "captions": [[0.0, 2.84, "How do I report an involuntarily missed meal break?"], [3.24, 8.48, "Employees are required to take an unpaid 30-minute meal break after working 5 hours or more."], [9.4, 12.741, "If you are involuntarily prevented from taking your break,"], [12.741, 18.56, "you must report it on your timecard by entering your total hours worked consecutively, without a gap."], [19.049, 21.928, "In this example, we are entering hours from 8:00 AM"], [22.169, 25.249, "to 2:00 PM, amounting to six consecutive hours."], [27.849, 32.889, "After pressing OK, you will immediately see the meal break penalty appear on your timecard."], [33.329, 36.328, "After submission, this will require your manager's approval."], [36.95, 41.35, "Workday will then automatically process the appropriate compensation in your next paycheck."]]}, "how-record-overtime": {"title": "How do I record overtime hours?", "transcript": ["How do I record overtime hours? If you worked longer than planned, simply click the time block you wish to adjust or add a new one. When recording overtime, use the standard Hours Worked time type. The system will automatically identify what counts as overtime for you.", "In this example, I am changing an end time from 5:00 PM to 9:00 PM, which adds 4 hours of overtime for the day. Once you update the time and press OK, the system recalculates your totals. You will see the daily total update to 12 hours in the bottom right corner, and the summary on the right will now accurately display those 4 hours of overtime. Workday will then automatically process the appropriate compensation in your next paycheck."], "captions": [[0.0, 1.88, "How do I record overtime hours?"], [2.44, 7.879, "If you worked longer than planned, simply click the time block you wish to adjust or add a new one."], [8.519, 12.24, "When recording overtime, use the standard Hours Worked time type."], [12.679, 16.359, "The system will automatically identify what counts as overtime for you."], [16.949, 20.388, "In this example, I am changing an end time from 5:00 PM"], [20.509, 23.949, "to 9:00 PM, which adds 4 hours of overtime for the day."], [24.509, 29.069, "Once you update the time and press OK, the system recalculates your totals."], [29.468, 33.469, "You will see the daily total update to 12 hours in the bottom right corner,"], [33.96, 38.08, "and the summary on the right will now accurately display those 4 hours of overtime."], [38.68, 43.639, "Workday will then automatically process the appropriate compensation in your next paycheck."]]}, "how-record-oncall": {"title": "How to record on-call standby and on-call hours worked", "transcript": ["How to record on-call standby and on-call hours worked. To record your on-call time, click on the day you worked in your timecard. In the Enter Time window, input your start and end times.", "For standby, select On-Call Standby Hours from the Time Type menu and press OK. To record active time, repeat these steps, select On-Call Hours Worked, and click OK to finish."], "captions": [[0.0, 3.72, "How to record on-call standby and on-call hours worked."], [4.319, 8.28, "To record your on-call time, click on the day you worked in your timecard."], [8.8, 12.559, "In the Enter Time window, input your start and end times."], [13.16, 18.8, "For standby, select On-Call Standby Hours from the Time Type menu and press"], [19.259, 27.178, "OK. To record active time, repeat these steps, select On-Call Hours Worked, and click OK to finish."]]}, "how-timecard-status": {"title": "How do I know the status of my timecard?", "transcript": ["How do I know the status of my timecard? Knowing your timecard status is simple by looking at the color-coded bars within your time blocks. First, notice the striped gray and white bar. This indicates your time is not yet submitted and requires your action.", "Watch as I click Submit for this standard timecard. Once submitted, the bar turns green, confirming it is approved. Because this entry contains no extra hours, it is auto-approved instantly upon submission.", "Now, let's look at a timecard where I'm adding overtime hours. After entering the extra time and clicking Submit, you will see a solid gray bar appear in the time blocks. This indicates that your timecard has been successfully submitted and is now routed to your manager for their formal approval."], "captions": [[0.0, 2.159, "How do I know the status of my timecard?"], [3.24, 8.96, "Knowing your timecard status is simple by looking at the color-coded bars within your time blocks."], [9.559, 12.639, "First, notice the striped gray and white bar."], [13.16, 17.199, "This indicates your time is not yet submitted and requires your action."], [17.979, 21.659, "Watch as I click Submit for this standard timecard."], [22.138, 24.739, "Once submitted, the bar turns green,"], [24.939, 26.795, "confirming it is approved."], [26.795, 33.219, "Because this entry contains no extra hours, it is auto-approved instantly upon submission."], [33.979, 49.22, "Now, let's look at a timecard where I'm adding overtime hours. After entering the extra time and clicking Submit,"], [49.74, 52.82, "you will see a solid gray bar appear in the time blocks."], [53.379, 60.419, "This indicates that your timecard has been successfully submitted and is now routed to your manager for their formal approval."]]}, "how-submit-timecard": {"title": "How do I submit my timecard?", "transcript": ["How do I submit my timecard in Workday? Click Review in the bottom right corner of the timecard page. In the submission window, verify your totals and click Submit. Repeat this process for the second week to finalize your submission.", "Before submitting, double-check your timecard to ensure all hours worked and absences are accurate. Verifying your daily totals in the bottom corner of each day."], "captions": [[0.0, 2.0, "How do I submit my timecard in Workday?"], [2.679, 6.12, "Click Review in the bottom right corner of the timecard page."], [6.6, 10.44, "In the submission window, verify your totals and click Submit."], [11.04, 14.88, "Repeat this process for the second week to finalize your submission."], [15.499, 21.139, "Before submitting, double-check your timecard to ensure all hours worked and absences are accurate."], [21.339, 24.299, "Verifying your daily totals in the bottom corner of each day."]]}, "how-approve-timecard": {"title": "How do leaders approve a timecard?", "transcript": ["How do leaders approve a timecard in Workday? As a leader, you have two convenient ways to access single timecards awaiting your approval. You can either select the request directly from the Awaiting Your Action section in the center of your Workday home page, or click the My Tasks inbox icon in the top right corner. In this example, we'll click the request under Awaiting Your Action, which takes us straight to the task for review.", "If you notice an alert in the orange box, this indicates an issue that should be investigated and resolved before you approve the timecard. Speak to your team member about it.", "Going back to the timecard to be reviewed, at the top, you'll see a summary of the employee's hours broken down by category, such as regular hours, overtime, on-call, and time off. To view specific entries in detailed time recordings, simply scroll down the page. Under Entries to Approve, you will see a detailed table with each entry recorded.", "Further down, you will see buttons to Approve or Send Back. If everything is correct, click Approve. However, if you do find an issue, we ask that you do not use the Send Back button. Instead, please speak with your team member directly to address and resolve the discrepancy. Once the discrepancy is resolved, you can come back here to approve it. For this demonstration, we are approving the timecard to complete the process."], "captions": [[0.0, 2.36, "How do leaders approve a timecard in Workday?"], [2.8, 7.799, "As a leader, you have two convenient ways to access single timecards awaiting your approval."], [8.12, 14.4, "You can either select the request directly from the Awaiting Your Action section in the center of your Workday home page,"], [14.4, 17.359, "or click the My Tasks inbox icon in the top right corner."], [17.879, 23.799, "In this example, we'll click the request under Awaiting Your Action, which takes us straight to the task for review."], [25.119, 27.258, "If you notice an alert in the orange box,"], [27.258, 32.319, "this indicates an issue that should be investigated and resolved before you approve the timecard."], [32.799, 34.359, "Speak to your team member about it."], [35.27, 37.935, "Going back to the timecard to be reviewed,"], [37.935, 46.629, "at the top, you'll see a summary of the employee's hours broken down by category, such as regular hours, overtime, on-call, and time off."], [47.91, 52.51, "To view specific entries in detailed time recordings, simply scroll down the page."], [53.359, 57.919, "Under Entries to Approve, you will see a detailed table with each entry recorded."], [60.84, 64.16, "Further down, you will see buttons to Approve or Send Back."], [64.64, 67.12, "If everything is correct, click Approve."], [67.719, 72.4, "However, if you do find an issue, we ask that you do not use the Send Back button."], [72.82, 77.74, "Instead, please speak with your team member directly to address and resolve the discrepancy."], [78.18, 82.06, "Once the discrepancy is resolved, you can come back here to approve it."], [84.98, 88.66, "For this demonstration, we are approving the timecard to complete the process."]]}, "how-bulk-approve": {"title": "How do leaders bulk approve time in Workday?", "transcript": ["How can leaders bulk approve time in Workday? As a leader, managing your team's time efficiently is straightforward in Workday. To begin, click More, the three dots at the bottom of your menu on the left, and select Team Time and Absence. On the right, click Review Time.", "In the pop-up window, locate the Period Schedule field. To find the correct option, click to view the dropdown options, select All, and choose AMER Biweekly, Monday to Sunday from the dropdown list. The date will populate automatically, though you can adjust this if needed. You can choose to view all workers, only those with hours requiring approval, or those who have not yet submitted their time. Click OK to proceed. At the top of the dashboard, use the navigation buttons to move between pay periods.", "You will see summary tiles displaying total worker counts, employees with time awaiting approval, those with no hours entered, and those with alerts. The alert will also be visible, marked with an orange triangle in the Submitted Time cell. An alert indicates a submission issue that requires your review. The specific issue isn't visible from this view, so you have two options. Navigate to the employee's profile to view their actual timecard, or reach out and inform them that there is an alert so they can correct it.", "Clicking on these numbers filters the table below. For instance, selecting the alert count highlights the specific employee. The table provides a comprehensive breakdown for each employee, including regular, overtime, and on-call hours. When you are ready to process these, select the check boxes for the employees you wish to approve and click Approve. Review the confirmation window and click Done to finalize. Once you return to the dashboard, you will notice an additional Approved Time column reflecting the hours you have just authorized."], "captions": [[0.0, 2.28, "How can leaders bulk approve time in Workday?"], [2.72, 7.319, "As a leader, managing your team's time efficiently is straightforward in Workday."], [9.24, 14.719, "To begin, click More, the three dots at the bottom of your menu on the left, and select"], [15.189, 19.189, "Team Time and Absence. On the right, click Review Time."], [19.669, 22.749, "In the pop-up window, locate the Period Schedule field."], [23.109, 30.988, "To find the correct option, click to view the dropdown options, select All, and choose AMER Biweekly, Monday to Sunday"], [31.5, 38.7, "from the dropdown list. The date will populate automatically, though you can adjust this if needed."], [39.1, 46.219, "You can choose to view all workers, only those with hours requiring approval, or those who have not yet submitted their time."], [46.94, 56.539, "Click OK to proceed. At the top of the dashboard, use the navigation buttons to move between pay periods."], [56.98, 60.26, "You will see summary tiles displaying total worker counts,"], [60.459, 62.419, "employees with time awaiting approval,"], [63.12, 66.766, "those with no hours entered, and those with alerts."], [66.766, 73.2, "The alert will also be visible, marked with an orange triangle in the Submitted Time cell."], [73.439, 76.88, "An alert indicates a submission issue that requires your review."], [77.399, 81.2, "The specific issue isn't visible from this view, so you have two options."], [82.0, 85.269, "Navigate to the employee's profile to view their actual timecard,"], [85.269, 89.04, "or reach out and inform them that there is an alert so they can correct it."], [91.559, 93.88, "Clicking on these numbers filters the table below."], [94.439, 98.119, "For instance, selecting the alert count highlights the specific employee."], [101.22, 108.46, "The table provides a comprehensive breakdown for each employee, including regular, overtime, and on-call hours."], [110.26, 116.42, "When you are ready to process these, select the check boxes for the employees you wish to approve and click Approve."], [121.51, 124.39, "Review the confirmation window and click Done to finalize."], [130.51, 137.67, "Once you return to the dashboard, you will notice an additional Approved Time column reflecting the hours you have just authorized."]]}, "how-oncall-eligible": {"title": "How do I identify if I am on-call eligible?", "transcript": ["How do I identify if I am on-call eligible in Workday? Open Workday. On the Workday welcome page, click the top right menu and select Profile. From the left-hand menu, click Job, then select the Organizations tab.", "Scroll down to On-Call Eligible. If it says Yes, you are eligible. If it says No, you aren't currently designated for on-call."], "captions": [[0.24, 4.279, "How do I identify if I am on-call eligible in Workday?"], [6.0, 11.12, "Open Workday. On the Workday welcome page, click the top right menu and select Profile."], [11.719, 16.44, "From the left-hand menu, click Job, then select the Organizations tab."], [16.979, 18.899, "Scroll down to On-Call Eligible."], [19.299, 21.739, "If it says Yes, you are eligible."], [21.939, 25.458, "If it says No, you aren't currently designated for on-call."]]}};
